export function toposort(nodes, edges) {
  if (!Array.isArray(nodes)) throw new TypeError('nodes must be an array');
  if (!Array.isArray(edges)) throw new TypeError('edges must be an array');

  const known = new Set();
  for (const name of nodes) {
    if (typeof name !== 'string') throw new TypeError('every node name must be a string');
    if (known.has(name)) throw new TypeError(`the node name ${name} appears twice`);
    known.add(name);
  }

  const indegree = new Map();
  const after = new Map();
  for (const name of nodes) {
    indegree.set(name, 0);
    after.set(name, []);
  }

  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) {
      throw new TypeError('every edge must be an array of exactly two strings');
    }
    const [from, to] = edge;
    if (typeof from !== 'string' || typeof to !== 'string') {
      throw new TypeError('every edge must be an array of exactly two strings');
    }
    if (!known.has(from) || !known.has(to)) {
      throw new RangeError(`the edge ${from} -> ${to} names a node that is not in nodes`);
    }
    after.get(from).push(to);
    indegree.set(to, indegree.get(to) + 1);
  }

  const placed = new Set();
  const out = [];
  while (out.length < nodes.length) {
    let pick = null;
    for (const name of nodes) {
      if (!placed.has(name) && indegree.get(name) === 0) {
        pick = name;
        break;
      }
    }
    if (pick === null) throw new Error('the edges make a cycle');
    placed.add(pick);
    out.push(pick);
    for (const next of after.get(pick)) indegree.set(next, indegree.get(next) - 1);
  }
  return out;
}
